function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  for (const w of words) {
    if (typeof w !== 'string' || w.length < 1 || w.length > 50) return 'Each word has 1 to 50 characters.';
    if (!/^[a-z]+$/.test(w)) return 'Words use only lowercase English letters.';
  }
  return null;
}

