function minimizeConcatenatedLength(words) {
  const code = (ch) => ch.charCodeAt(0) - 97;
  const empty = () => Array.from({ length: 26 }, () => new Array(26).fill(Infinity));
  let dp = empty();
  dp[code(words[0][0])][code(words[0].at(-1))] = words[0].length;

  for (let i = 1; i < words.length; i++) {
    const word = words[i];
    const first = code(word[0]);
    const last = code(word.at(-1));
    const next = empty();
    for (let head = 0; head < 26; head++) {
      for (let tail = 0; tail < 26; tail++) {
        const length = dp[head][tail];
        if (length === Infinity) continue;
        const appended = length + word.length - (tail === first ? 1 : 0);
        next[head][last] = Math.min(next[head][last], appended);
        const prepended = length + word.length - (last === head ? 1 : 0);
        next[first][tail] = Math.min(next[first][tail], prepended);
      }
    }
    dp = next;
  }

  let best = Infinity;
  for (const row of dp) {
    best = Math.min(best, ...row);
  }
  return best;
}

