function minimizeConcatenatedLength(words) {
  const join = (x, y) => (x[x.length - 1] === y[0] ? x + y.slice(1) : x + y);
  const n = words.length;
  let best = Infinity;
  // Bit i - 1 of choice says whether words[i] goes in front of the string built so far.
  for (let choice = 0; choice < 2 ** (n - 1); choice++) {
    let str = words[0];
    for (let i = 1; i < n; i++) {
      str = (choice >> (i - 1)) & 1 ? join(words[i], str) : join(str, words[i]);
    }
    best = Math.min(best, str.length);
  }
  return best;
}

