function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (alphabet, maxLength) => {
    const length = pick(1, maxLength);
    let text = '';
    for (let k = 0; k < length; k++) text += letters[pick(0, alphabet - 1)];
    return text;
  };
  if (size === 'large') {
    const alphabet = pick(2, 26);
    return [Array.from({ length: 1000 }, () => word(alphabet, pick(1, 50)))];
  }
  const n = pick(1, 9);
  const alphabet = pick(1, 4);
  const maxLength = pick(1, 4);
  return [Array.from({ length: n }, () => word(alphabet, maxLength))];
}
